#' Default S3 plot method for process objects (derived from `process()`)
#'
#' This function sets up the default plotting method
#' for outputs from process function
#'
#' @param x process object as generated by process
#' @param plot_type defaults to both plots. Can specify 'mass' or
#'        'rate' curves by themselves.
#' @param cex size of plots features
#' @param ... other options passed to plot
#' @return plot
#' @method plot process
#' @importFrom graphics legend lines par plot axis text segments grid
#'
#' @export

plot.process <- function (x, plot_type = NULL, cex = 1, ...) {

  p_massloss <- function (data) {
    max_mass <- max(data$mass_T, na.rm = TRUE)
    y_limit_top <- max_mass * 1.3

    col_moisture <- "steelblue"
    col_volatiles <- "palegreen3"
    col_fixed     <- "goldenrod"

    plot(data$time, data$mass_T,
         type = "n",
         xlab = "Time (min)",
         ylim = c(0, y_limit_top),
         yaxt = "n", xaxt = "n",
         ylab = "Mass remaining (mg)",
         cex.lab = 1.2 * cex,
         main = "Mass Loss Profiles")

    x_ticks <- pretty(data$time)
    axis(side = 1, at = x_ticks, labels = x_ticks, cex.axis = cex)
    y_ticks <- pretty(c(0, max_mass))
    axis(side = 2, at = y_ticks, labels = y_ticks, cex.axis = cex, las = 1)

    legend_labels <- c()
    legend_cols   <- c()

    m_idx <- which(data$stage == "moisture_content")
    if (length(m_idx) > 0) {
      m_idx <- m_idx[order(data$time[m_idx])]
      points(data$time[m_idx], data$mass_T[m_idx],
             col = col_moisture, pch = 20, cex = 0.5 * cex)

      m_start <- min(data$time[m_idx])
      m_end   <- max(data$time[m_idx])
      legend_labels <- c(legend_labels,
                         sprintf("Moisture (%.2f–%.2f min)", m_start, m_end))
      legend_cols   <- c(legend_cols, col_moisture)
    }

    v_idx <- which(data$stage == "volatile_matter")
    if (length(v_idx) > 0) {
      v_idx <- v_idx[order(data$time[v_idx])]
      points(data$time[v_idx], data$mass_T[v_idx],
             col = col_volatiles, pch = 20, cex = 0.5 * cex)

      v_start <- min(data$time[v_idx])
      v_end   <- max(data$time[v_idx])
      legend_labels <- c(legend_labels,
                         sprintf("Volatiles (%.2f–%.2f min)", v_start, v_end))
      legend_cols   <- c(legend_cols, col_volatiles)
    }

    f_idx <- which(data$stage == "fixed_carbon")
    if (length(f_idx) > 0) {
      f_idx <- f_idx[order(data$time[f_idx])]
      points(data$time[f_idx], data$mass_T[f_idx],
             col = col_fixed, pch = 20, cex = 0.5 * cex)

      f_start <- min(data$time[f_idx])
      f_end   <- max(data$time[f_idx])
      legend_labels <- c(legend_labels,
                         sprintf("Fixed Carbon (%.2f–%.2f min)", f_start, f_end))
      legend_cols   <- c(legend_cols, col_fixed)
    }

    if (length(legend_labels) > 0) {
      legend("topright",
             legend = legend_labels,
             col    = legend_cols,
             lwd    = 2,
             pch    = 20,
             bty    = "n",
             cex    = 0.8 * cex)
    }
  }




  p_dtg <- function (data) {

    max_rate <- max(data$deriv, na.rm = TRUE)

    plot(data$time, data$deriv,
         xlab = 'Time (min)',
         ylim = c(0, max_rate * 1.1),
         ylab = expression(paste('Rate of mass loss during pyrolysis (-dm/dT)(C'^1*')')),
         pch = 20,
         cex = 0.5 * cex,
         cex.lab = 1.2 * cex,
         yaxt = 'n', xaxt = 'n',
         main = "DTG Curve")

    x_ticks <- pretty(data$time)
    axis(side = 1, at = x_ticks, labels = x_ticks, cex.axis = cex)

    y_ticks <- pretty(c(0, max_rate), n = 5)
    axis(side = 2, at = y_ticks, labels = y_ticks, cex.axis = cex, las = 1)


    start_time <- min(data$time, na.rm = TRUE)
    end_time   <- max(data$time, na.rm = TRUE)

    axis(side = 1,
         at = c(start_time, end_time),
         labels = FALSE,
         col.ticks = "red",
         tcl = -0.25)


    offset_y <- -max_rate * 0.08

    text(x = start_time,
         y = offset_y,
         labels = round(start_time, 2),
         col = "red",
         cex = 0.6 * cex,
         xpd = TRUE)

    text(x = end_time,
         y = offset_y,
         labels = round(end_time, 2),
         col = "red",
         cex = 0.6 * cex,
         xpd = TRUE)
  }


  oldpar <- par(no.readonly = TRUE)
  on.exit(par(oldpar))

  if (!is.null(plot_type) && plot_type == 'mass') {
    par(mar = c(4.5, 4.5, 3, 1))
    p_massloss(x$all_data)

  } else if (!is.null(plot_type) && plot_type == 'rate') {
    par(mar = c(4.5, 4.5, 3, 1))
    p_dtg(x$pyrolysis_data)

  } else {
    par(mfrow = c(1,2), mar = c(4.5, 4.5, 3, 1), oma = c(0, 0, 2, 0))
    p_massloss(x$all_data)
    p_dtg(x$pyrolysis_data)
  }
}
